<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import { api,http } from '@/api/http'
import { useAuthStore } from '@/stores/auth'
import type { PageData,SaleOrder } from '@/types'
import { canCancel,canReturn,orderStatus } from '@/utils/orderStatus'
import { ElMessage,ElMessageBox } from 'element-plus'
import { Download } from '@element-plus/icons-vue'
const auth=useAuthStore(),list=ref<SaleOrder[]>([]),total=ref(0),page=ref(1),keyword=ref(''),status=ref(''),loading=ref(false),detail=ref<SaleOrder>(),detailDialog=ref(false),returnDialog=ref(false),returnReason=ref('商品完好退回'),returnQty=ref<Record<number,number>>({})
const canOperate=computed(()=>auth.can('ADMIN','CASHIER'))
async function load(){loading.value=true;try{const d=await api<PageData<SaleOrder>>(http.get('/orders',{params:{keyword:keyword.value,status:status.value,page:page.value,pageSize:15}}));list.value=d.items;total.value=d.total}finally{loading.value=false}}
async function view(row:SaleOrder){detail.value=await api< SaleOrder>(http.get(`/orders/${row.id}`));detailDialog.value=true}
async function cancel(row:SaleOrder){await ElMessageBox.confirm(`确认取消订单 ${row.orderNo}？预占库存将立即释放。`,'取消订单',{type:'warning'});await api(http.post(`/orders/${row.id}/cancel`));ElMessage.success('订单已取消，预占库存已释放');load()}
async function pay(row:SaleOrder){await ElMessageBox.confirm(`对订单 ${row.orderNo} 执行模拟收款？`,'模拟收款');await api(http.post(`/orders/${row.id}/pay`,{idempotencyKey:crypto.randomUUID(),paymentMethod:'STORE'}));ElMessage.success('模拟收款完成');load()}
async function openReturn(row:SaleOrder){detail.value=await api<SaleOrder>(http.get(`/orders/${row.id}`));returnQty.value={};for(const item of detail.value.items||[])returnQty.value[item.id]=0;returnDialog.value=true}
async function submitReturn(){if(!detail.value)return;const items=Object.entries(returnQty.value).filter(([,q])=>q>0).map(([id,q])=>({saleItemId:Number(id),quantity:q}));if(!items.length){ElMessage.warning('请填写退货数量');return}await api(http.post(`/orders/${detail.value.id}/returns`,{idempotencyKey:crypto.randomUUID(),reason:returnReason.value,items}));ElMessage.success('退货完成，库存已回补');returnDialog.value=false;load()}
async function exportCsv(){const now=new Date(),from=new Date(now.getFullYear(),now.getMonth(),1).toISOString().slice(0,10),to=now.toISOString().slice(0,10);const response=await http.get('/stats/orders.csv',{params:{from,to},responseType:'blob'});const url=URL.createObjectURL(response.data);const a=document.createElement('a');a.href=url;a.download=`sales-${from}-${to}.csv`;a.click();URL.revokeObjectURL(url)}
onMounted(load)
</script>
<template><div><div class="page-head"><div><h2>{{ auth.user?.role==='MEMBER'?'我的订单':'销售订单' }}</h2><p>订单金额使用成交快照；净额为实收减退款。</p></div><el-button v-if="canOperate" :icon="Download" @click="exportCsv">导出本月 CSV</el-button></div><section class="panel"><div class="toolbar"><el-input v-model="keyword" clearable placeholder="订单号" style="width:280px" @keyup.enter="page=1;load()"/><el-select v-model="status" clearable placeholder="全部状态" style="width:180px" @change="page=1;load()"><el-option v-for="(v,k) in orderStatus" :key="k" :label="v.label" :value="k"/></el-select><el-button @click="page=1;load()">查询</el-button></div><el-table v-loading="loading" :data="list" stripe><el-table-column prop="orderNo" label="订单号" min-width="190"/><el-table-column label="来源" width="100"><template #default="s">{{ s.row.channel==='MINIAPP'?'微信小程序':'Web 收银' }}</template></el-table-column><el-table-column v-if="auth.user?.role!=='MEMBER'" prop="memberName" label="会员" width="110"/><el-table-column label="状态" width="120"><template #default="s"><el-tag :type="orderStatus[s.row.status]?.type||'info'">{{ orderStatus[s.row.status]?.label||s.row.status }}</el-tag></template></el-table-column><el-table-column label="订单 / 退款" width="150"><template #default="s">¥{{ Number(s.row.totalAmount).toFixed(2) }} / <span class="danger-text">¥{{ Number(s.row.refundAmount).toFixed(2) }}</span></template></el-table-column><el-table-column prop="createdAt" label="创建时间" min-width="170"/><el-table-column label="操作" min-width="230" fixed="right"><template #default="s"><el-button link @click="view(s.row)">详情</el-button><el-button v-if="canCancel(s.row.status)" link type="warning" @click="cancel(s.row)">取消</el-button><el-button v-if="canOperate&&s.row.status==='PENDING_PAYMENT'" link type="primary" @click="pay(s.row)">收款</el-button><el-button v-if="canOperate&&canReturn(s.row.status)" link type="danger" @click="openReturn(s.row)">退货</el-button></template></el-table-column></el-table><el-pagination style="margin-top:18px;justify-content:flex-end" background layout="total,prev,pager,next" :total="total" :page-size="15" v-model:current-page="page" @current-change="load"/></section><el-dialog v-model="detailDialog" title="销售单详情" width="760px"><el-descriptions v-if="detail" :column="2" border><el-descriptions-item label="订单号">{{ detail.orderNo }}</el-descriptions-item><el-descriptions-item label="状态">{{ orderStatus[detail.status]?.label }}</el-descriptions-item><el-descriptions-item label="订单金额">¥{{ detail.totalAmount }}</el-descriptions-item><el-descriptions-item label="退款金额">¥{{ detail.refundAmount }}</el-descriptions-item></el-descriptions><el-table :data="detail?.items||[]" style="margin-top:16px"><el-table-column prop="productName" label="商品"/><el-table-column prop="specification" label="规格"/><el-table-column prop="unitPrice" label="成交单价"/><el-table-column prop="quantity" label="数量"/><el-table-column prop="returnedQty" label="已退"/></el-table><div class="notice" style="margin-top:14px">商品名称、规格、单位和成交价均为下单时快照。</div></el-dialog><el-dialog v-model="returnDialog" title="处理退货" width="660px"><div class="notice">退货确认后立即回补当前库存；累计退货数量不能超过原销售数量。</div><el-table :data="detail?.items||[]" style="margin:14px 0"><el-table-column prop="productName" label="商品"/><el-table-column label="可退" width="90"><template #default="s">{{ s.row.quantity-s.row.returnedQty }}</template></el-table-column><el-table-column label="本次退货" width="160"><template #default="s"><el-input-number v-model="returnQty[s.row.id]" :min="0" :max="s.row.quantity-s.row.returnedQty"/></template></el-table-column></el-table><el-form-item label="退货原因" required><el-input v-model="returnReason"/></el-form-item><template #footer><el-button @click="returnDialog=false">取消</el-button><el-button type="danger" @click="submitReturn">确认退货并回补库存</el-button></template></el-dialog></div></template>
